for batch in imagenet_loader:
    inputs, targets = batch
    inputs = inputs.to(device)
    targets = targets.to(device)

    outputs = model(inputs)
    
    _, preds = torch.max(outputs, 1)
    correct = (preds == targets).sum().item()
    mean_acc += correct
    total_samples += inputs.size(0)
    mean_acc_class_biased += (preds[targets == for_biased_class] == for_biased_class).sum().item()
    total_samples_class_biased += (
        targets == for_biased_class
    ).sum().item()
    
    
    imagenet_loader.set_postfix({"accuracy": f"{mean_acc / total_samples}","accuracy_class_biased": f"{1.0 if total_samples_class_biased == 0 else mean_acc_class_biased / total_samples_class_biased}"})
